import { Bell, BellRing, Building2, CalendarDays, ChartNoAxesCombined, CircleHelp, ClipboardList, KeyRound, LayoutDashboard, LogOut, Menu, MessageSquare, Moon, PlayCircle, Plus, Send, ShieldCheck, Sun, UserPlus, UserRound, Users, Wrench, X } from "lucide-react";
import { FormEvent, useEffect, useMemo, useState } from "react";
import { useLanguage } from "../contexts/LanguageContext";
import { useTheme } from "../contexts/ThemeContext";
import { type DemoAppointment, type DemoConversation, type DemoInquiry, type DemoPerson, type DemoRole, type DemoState, type DemoTicket, demoRequest } from "../lib/demoApi";

type View = "overview" | "analytics" | "requests" | "calendar" | "messages" | "inquiries" | "reminders" | "profile" | "people";
const demoPassword = "MaintainrDemo2026!";
const accounts: { role: DemoRole; email: string; label: string; icon: typeof Building2 }[] = [
  { role: "PROPERTY_MANAGER", email: "manager@demo.maintainr.app", label: "Property Manager", icon: Building2 },
  { role: "TENANT", email: "resident@demo.maintainr.app", label: "Resident", icon: UserRound },
  { role: "TECHNICIAN", email: "technician@demo.maintainr.app", label: "Field Technician", icon: Wrench },
  { role: "FLAT_OWNER", email: "owner@demo.maintainr.app", label: "Flat Owner", icon: ShieldCheck },
];
const roleNames: Record<DemoRole, string> = { PROPERTY_MANAGER: "Property Manager", TENANT: "Resident", TECHNICIAN: "Field Technician", FLAT_OWNER: "Flat Owner" };
const roleGuidance: Record<DemoRole, string> = { PROPERTY_MANAGER: "Assign work, manage people, and see the full portfolio.", TENANT: "Report issues, attach context, and follow progress for your unit.", TECHNICIAN: "Work assigned jobs, update progress, and record proof of completion.", FLAT_OWNER: "Review maintenance activity for your unit. This role is read-only." };
const statusTone: Record<DemoTicket["status"], string> = { OPEN: "border-rose-400/30 bg-rose-50 text-rose-700 dark:bg-rose-400/10 dark:text-rose-300", ASSIGNED: "border-sky-400/30 bg-sky-50 text-sky-700 dark:bg-sky-400/10 dark:text-sky-300", IN_PROGRESS: "border-amber-400/30 bg-amber-50 text-amber-800 dark:bg-amber-400/10 dark:text-amber-300", RESOLVED: "border-emerald-400/30 bg-emerald-50 text-emerald-700 dark:bg-emerald-400/10 dark:text-emerald-300" };

function WorkspaceThemeToggle() { const { theme, toggleTheme } = useTheme(); const { t } = useLanguage(); if (!toggleTheme) return null; const dark = theme === "dark"; return <button type="button" onClick={toggleTheme} aria-label={dark ? t("Switch to light mode", "التبديل للوضع الفاتح") : t("Switch to dark mode", "التبديل للوضع الداكن")} className="maintainr-demo-utility grid size-10 place-items-center rounded-xl text-slate-600 transition hover:text-teal-700 dark:text-slate-300 dark:hover:text-teal-200">{dark ? <Sun size={17}/> : <Moon size={17}/>}</button>; }

export function ProductExperiencePage() {
  const { t } = useLanguage(); const [state, setState] = useState<DemoState | null>(null); const [checking, setChecking] = useState(true); const [error, setError] = useState("");
  useEffect(() => { demoRequest("session").then(setState).catch(() => setState(null)).finally(() => setChecking(false)); }, []);
  if (checking) return <main className="grid min-h-screen place-items-center bg-[#edf5f3] text-[#47615d] dark:bg-[#080b12] dark:text-slate-300">{t("Opening demo workspace…", "يتم فتح مساحة العمل التجريبية…")}</main>;
  if (!state) return <DemoSignIn error={error} onSignIn={async (email, password) => { setError(""); try { setState(await demoRequest("login", { email, password })); } catch (reason) { setError(reason instanceof Error ? reason.message : t("Unable to sign in.", "تعذر تسجيل الدخول.")); } }}/>;
  return <DemoWorkspace state={state} onState={setState} onLogout={async () => { await demoRequest("logout").catch(() => undefined); setState(null); }}/>;
}

function DemoSignIn({ error, onSignIn }: { error: string; onSignIn: (email: string, password: string) => Promise<void> }) {
  const { t } = useLanguage(); const [email, setEmail] = useState(accounts[0].email); const [password, setPassword] = useState(demoPassword); const [busy, setBusy] = useState(false);
  const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); await onSignIn(email, password); setBusy(false); };
  return <main className="min-h-screen bg-[#edf5f3] px-5 py-8 text-[#172a27] dark:bg-[#080b12] dark:text-slate-100 lg:px-8"><div className="mx-auto grid min-h-[calc(100vh-4rem)] max-w-6xl overflow-hidden rounded-[2rem] border border-[#cde7e3] bg-white shadow-[0_28px_80px_rgba(23,32,51,.13)] dark:border-white/[.08] dark:bg-[#101521] lg:grid-cols-[.9fr_1.1fr]"><section className="bg-[#0b0f18] p-8 text-white sm:p-12"><a href="/" className="text-sm font-semibold text-teal-200">← {t("Back to site", "العودة إلى الموقع")}</a><p className="mt-16 text-xs font-bold tracking-[.18em] text-teal-200">{t("MAINTAINR DEMO", "عرض Maintainr")}</p><h1 className="mt-5 max-w-md text-4xl font-semibold leading-[1.02] tracking-[-.055em] sm:text-5xl">{t("Sign in to the same Maintainr operating workspace.", "سجّل الدخول إلى مساحة عمليات Maintainr نفسها.")}</h1><p className="mt-6 max-w-md leading-7 text-slate-300">{t("The screens and role actions mirror Maintainr SaaS. Only the demo database and demo accounts are separate.", "تعكس الشاشات وإجراءات الأدوار Maintainr SaaS. قاعدة بيانات العرض وحساباته فقط منفصلة.")}</p><div className="mt-6 flex max-w-md items-start gap-3 rounded-2xl border border-teal-200/20 bg-teal-300/10 p-4 text-sm leading-6 text-teal-50"><ShieldCheck size={18} className="mt-1 shrink-0"/><span>{t("Safe sandbox: actions here never touch live customer workspaces or SaaS records.", "بيئة آمنة: الإجراءات هنا لا تؤثر أبداً على مساحات العملاء أو سجلات SaaS الحية.")}</span></div><div className="mt-12 grid gap-3">{accounts.map(({ role, email: accountEmail, label, icon: Icon }) => <button key={role} type="button" onClick={() => { setEmail(accountEmail); setPassword(demoPassword); }} className={`flex items-center gap-3 rounded-2xl border p-4 text-start transition ${email === accountEmail ? "border-teal-200/70 bg-white/10" : "border-white/10 bg-white/[.03] hover:bg-white/[.08]"}`}><span className="grid size-10 place-items-center rounded-xl bg-teal-400/10 text-teal-200"><Icon size={18}/></span><span><b className="block text-sm">{label}</b><span className="mt-1 block text-xs leading-5 text-slate-300">{roleGuidance[role]}</span><span className="mt-1 block text-[10px] text-slate-500">{accountEmail}</span></span></button>)}</div></section><section className="flex items-center p-8 sm:p-12"><form onSubmit={submit} className="mx-auto w-full max-w-md"><span className="grid size-12 place-items-center rounded-2xl bg-teal-50 text-teal-700 dark:bg-teal-400/10 dark:text-teal-200"><PlayCircle size={24}/></span><p className="mt-8 text-xs font-bold uppercase tracking-[.18em] text-teal-700 dark:text-teal-200">{t("Secure demo access", "وصول عرض آمن")}</p><h2 className="mt-3 text-3xl font-semibold tracking-[-.04em]">{t("Open demo workspace", "افتح مساحة العمل التجريبية")}</h2><p className="mt-3 text-sm leading-6 text-[#526176] dark:text-slate-400">{t("Use a role below to explore the same workspace navigation, setup, tickets, calendar, messages, inquiries, profile, and reminders in safe demo-only data.", "استخدم دوراً أدناه لاستكشاف تنقل مساحة العمل والإعدادات والبلاغات والتقويم والرسائل والاستفسارات والملف الشخصي والتذكيرات ضمن بيانات عرض آمنة فقط.")}</p><label className="mt-8 block text-sm font-semibold">{t("Demo email", "البريد التجريبي")}<input value={email} onChange={(event) => setEmail(event.target.value)} type="email" className="mt-2 h-12 w-full rounded-xl border border-slate-200 bg-white px-4 text-sm text-[#172a27] outline-none focus:border-teal-600 dark:border-white/[.12] dark:bg-white/[.04] dark:text-white" required/></label><label className="mt-5 block text-sm font-semibold">{t("Demo password", "كلمة مرور العرض")}<input value={password} onChange={(event) => setPassword(event.target.value)} type="password" className="mt-2 h-12 w-full rounded-xl border border-slate-200 bg-white px-4 text-sm text-[#172a27] outline-none focus:border-teal-600 dark:border-white/[.12] dark:bg-white/[.04] dark:text-white" required/></label>{error && <p className="mt-4 rounded-xl bg-rose-50 p-3 text-sm text-rose-700 dark:bg-rose-400/10 dark:text-rose-200">{error}</p>}<button disabled={busy} className="mt-7 h-12 w-full rounded-xl bg-teal-700 text-sm font-semibold text-white hover:bg-teal-800 disabled:bg-slate-300">{busy ? t("Signing in…", "يتم تسجيل الدخول…") : t("Start demo", "ابدأ العرض")}</button><p className="mt-5 text-center text-xs leading-5 text-[#526176] dark:text-slate-400">{t("The default demo password is public for evaluation. It is not a live customer password.", "كلمة مرور العرض الافتراضية عامة للتقييم وليست كلمة مرور عميل حية.")}</p></form></section></div></main>;
}

function DemoWorkspace({ state, onState, onLogout }: { state: DemoState; onState: (next: DemoState) => void; onLogout: () => Promise<void> }) {
  const { t, direction, toggleLanguage } = useLanguage(); const [view, setView] = useState<View>("overview"); const [menuOpen, setMenuOpen] = useState(false); const [error, setError] = useState(""); const role = state.account.role;
  const run = async (action: string, payload: Record<string, unknown> = {}) => { setError(""); try { const next = await demoRequest(action, payload); onState(next); return next; } catch (reason) { setError(reason instanceof Error ? reason.message : t("Unable to update the isolated demo workspace.", "تعذر تحديث مساحة العرض المعزولة.")); return undefined; } };
  const RoleIcon = useMemo(() => accounts.find((item) => item.role === role)?.icon ?? Wrench, [role]); const initials = state.account.name.split(/\s+/).filter(Boolean).slice(0, 2).map(part => part[0]).join("").toUpperCase(); const unread = state.reminders.filter(reminder => !reminder.isAcknowledged).length;
  const titles: Record<View, string> = { overview: role === "PROPERTY_MANAGER" ? t("Maintenance overview", "نظرة عامة على الصيانة") : t("Role overview", "نظرة عامة على الدور"), analytics: t("Analytics", "التحليلات"), requests: role === "TECHNICIAN" ? t("Assigned jobs", "المهام المسندة") : role === "TENANT" ? t("My requests", "طلباتي") : t("Ticket operations", "عمليات البلاغات"), calendar: t("Calendar", "التقويم"), messages: t("Messages", "الرسائل"), inquiries: t("Inquiries", "الاستفسارات"), reminders: t("Maintenance reminders", "تذكيرات الصيانة"), profile: t("Profile & security", "الملف الشخصي والأمان"), people: t("People and access", "الأشخاص والوصول") };
  return <div className="maintainr-demo-shell min-h-screen bg-[#edf5f3] text-[#172a27] dark:bg-[#080b12] dark:text-slate-100">{menuOpen && <button aria-label={t("Close navigation", "إغلاق التنقل")} onClick={() => setMenuOpen(false)} className="fixed inset-0 z-40 bg-[#080b12]/45 lg:hidden"/>}<aside className={`maintainr-demo-rail fixed inset-y-0 left-0 z-50 flex w-72 flex-col overflow-y-auto overscroll-contain border-r border-white/[.07] bg-[#0b0f18] p-5 text-slate-100 transition-transform lg:translate-x-0 ${menuOpen ? "translate-x-0" : "-translate-x-full"}`}><div className="flex items-center justify-between"><a href="/" className="flex min-w-0 items-center gap-3"><span className="grid size-10 shrink-0 place-items-center rounded-2xl bg-teal-600 text-white shadow-lg shadow-teal-600/20"><Wrench size={20}/></span><span className="min-w-0"><span className="block truncate font-semibold tracking-tight">Maintainr</span><span className="block text-[10px] uppercase tracking-[.22em] text-slate-500">{t("Operations workspace", "مساحة العمليات")}</span></span></a><button className="text-slate-500 lg:hidden" onClick={() => setMenuOpen(false)} aria-label={t("Close navigation", "إغلاق التنقل")}><X size={18}/></button></div><button onClick={() => { setView("profile"); setMenuOpen(false); }} className="maintainr-demo-rail-panel mt-8 flex w-full items-center gap-3 rounded-2xl border border-white/[.08] bg-white/[.03] p-3 text-start transition hover:bg-white/[.06]"><span className="grid size-10 shrink-0 place-items-center overflow-hidden rounded-xl bg-teal-400/10 text-teal-200">{state.account.avatarUrl ? <img src={state.account.avatarUrl} alt="" className="size-full object-cover"/> : <RoleIcon size={18}/>}</span><span className="min-w-0"><span className="block truncate text-sm font-semibold">{roleNames[role]}</span><span className="mt-1 block truncate text-xs text-slate-500">{t("Role workspace", "مساحة الدور")}</span></span></button><p className="mt-8 px-3 text-[10px] font-bold uppercase tracking-[.2em] text-slate-500">{t("Workspace", "مساحة العمل")}</p><DemoNav role={role} view={view} onView={(next) => { setView(next); setMenuOpen(false); }}/><div className="mt-auto space-y-3"><div className="maintainr-demo-rail-panel rounded-2xl border border-white/[.08] bg-white/[.03] p-4"><ShieldCheck size={18} className="text-teal-200"/><p className="mt-4 text-xs font-semibold">{t("Isolated demo", "عرض معزول")}</p><p className="mt-2 text-xs leading-5 text-slate-400">{t("Commercial demo database · never connected to live SaaS", "قاعدة بيانات العرض التجاري · لا تتصل أبداً بـ SaaS الحي")}</p><p className="mt-2 text-xs leading-5 text-slate-400">{t("Same portal pattern. Separate demo-only records.", "نمط البوابة نفسه. سجلات عرض منفصلة فقط.")}</p></div><button onClick={onLogout} className="maintainr-demo-rail-signout flex w-full items-center gap-3 rounded-xl px-3 py-3 text-sm text-slate-400 transition hover:bg-white/[.05] hover:text-white"><LogOut size={17}/>{t("Sign out", "تسجيل الخروج")}</button></div></aside><main className="min-w-0 lg:pl-72"><header className="sticky top-0 z-30 flex h-20 items-center justify-between border-b border-[#d9e8e5] bg-[#edf5f3]/90 px-5 backdrop-blur-xl dark:border-white/[.07] dark:bg-[#080b12]/85 lg:px-10"><div className="flex min-w-0 items-center gap-3"><button className="text-[#47615d] dark:text-slate-400 lg:hidden" onClick={() => setMenuOpen(true)} aria-label={t("Open navigation", "فتح التنقل")}><Menu/></button><div className="hidden lg:block"><p className="text-[10px] font-bold uppercase tracking-[.2em] text-[#6a837f] dark:text-slate-500">{t("Maintainr workspace", "مساحة Maintainr")}</p><p className="mt-1 truncate text-sm font-semibold text-[#25413d] dark:text-slate-300">{roleNames[role]}</p></div></div><div className="flex items-center gap-2 sm:gap-3"><button onClick={() => setView("messages")} aria-label={t("Open messages", "فتح الرسائل")} className="maintainr-demo-utility grid size-10 place-items-center rounded-xl text-[#47615d] dark:text-slate-300"><MessageSquare size={17}/></button><button onClick={() => setView("reminders")} aria-label={unread ? t(`${unread} unread reminders`, `${unread} تذكيرات غير مقروءة`) : t("Open notifications", "فتح الإشعارات")} className="maintainr-demo-utility relative grid size-10 place-items-center rounded-xl text-[#47615d] dark:text-slate-300"><Bell size={17}/>{unread > 0 && <span className="absolute -right-1 -top-1 grid min-w-4 place-items-center rounded-full bg-rose-500 px-1 text-[10px] font-bold leading-4 text-white">{Math.min(9, unread)}</span>}</button><button onClick={toggleLanguage} className="maintainr-demo-utility rounded-xl px-3 py-2 text-xs font-medium text-[#47615d] dark:text-slate-300" aria-label={direction === "rtl" ? t("Switch to English", "التبديل إلى الإنجليزية") : t("Switch to Arabic", "التبديل إلى العربية")}>{direction === "rtl" ? "EN" : "العربية"}</button><WorkspaceThemeToggle/><div className="hidden items-center gap-2 rounded-full border border-[#d9e8e5] bg-white/70 px-3 py-2 text-xs text-[#56716d] dark:border-white/[.08] dark:bg-white/[.03] dark:text-slate-400 md:flex"><span className="size-2 rounded-full bg-emerald-400"/>{t("Workspace ready", "مساحة العمل ج��هزة")}</div><button onClick={() => setView("profile")} aria-label={t("Open profile", "فتح الملف الشخصي")} className="flex size-10 items-center justify-center rounded-xl bg-gradient-to-br from-teal-400 to-sky-400 text-xs font-bold text-[#090b12]">{initials}</button></div></header><section className="p-5 pb-24 lg:p-10 lg:pb-14"><div className="mb-8 flex min-w-0 flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-[.2em] text-teal-700 dark:text-teal-200">{view === "overview" && role === "PROPERTY_MANAGER" ? t("Manager command center", "مركز قيادة المدير") : t("Role workspace", "مساحة الدور")}</p><h1 className="mt-2 text-3xl font-semibold tracking-[-.04em] text-[#172a27] dark:text-white sm:text-4xl">{titles[view]}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-[#56716d] dark:text-slate-400">{t("The same role-aware portal pattern as Maintainr SaaS, operating only on safe isolated demo records.", "نمط البوابة نفسه حسب الدور كما في Maintainr SaaS، يعمل فقط على سجلات عرض معزولة وآمنة.")}</p></div>{view !== "overview" && <button onClick={() => setView("overview")} className="h-10 rounded-xl border border-[#cfe0dc] bg-white px-4 text-sm font-semibold text-teal-700 dark:border-white/[.1] dark:bg-white/[.03] dark:text-teal-200">{t("Back to overview", "العودة إلى النظرة العامة")}</button>}</div>{error && <p className="mb-5 rounded-xl bg-rose-50 p-3 text-sm text-rose-700 dark:bg-rose-400/10 dark:text-rose-200">{error}</p>}{view === "overview" && <Overview state={state} role={role} onView={setView} onRun={run}/>} {view === "analytics" && <Analytics state={state}/>} {view === "requests" && <Requests state={state} onRun={run}/>} {view === "calendar" && <Calendar state={state} onRun={run}/>} {view === "messages" && <Messages conversations={state.conversations} onRun={run}/>} {view === "inquiries" && <Inquiries inquiries={state.inquiries}/>} {view === "reminders" && <Reminders state={state} onRun={run}/>} {view === "profile" && <Profile state={state} onRun={run}/>} {view === "people" && role === "PROPERTY_MANAGER" && <People state={state} onRun={run}/>}</section></main></div>;
}

function DemoNav({ role, view, onView }: { role: DemoRole; view: View; onView: (view: View) => void }) { const { t } = useLanguage(); const items = role === "PROPERTY_MANAGER" ? [{ id: "overview" as const, label: t("Overview", "نظرة عامة"), icon: LayoutDashboard }, { id: "analytics" as const, label: t("Analytics", "التحليلات"), icon: ChartNoAxesCombined }, { id: "requests" as const, label: t("Tickets", "البلاغات"), icon: ClipboardList }, { id: "calendar" as const, label: t("Calendar", "التقويم"), icon: CalendarDays }, { id: "messages" as const, label: t("Messages", "الرسائل"), icon: MessageSquare }, { id: "inquiries" as const, label: t("Inquiries", "الاستفسارات"), icon: CircleHelp }, { id: "people" as const, label: t("People", "الأشخاص"), icon: Users }, { id: "reminders" as const, label: t("Reminders", "التذكيرات"), icon: BellRing }, { id: "profile" as const, label: t("Profile", "الملف الشخصي"), icon: UserRound }] : [{ id: "overview" as const, label: role === "TECHNICIAN" ? t("Today", "اليوم") : t("Overview", "نظرة عامة"), icon: LayoutDashboard }, { id: "requests" as const, label: role === "TECHNICIAN" ? t("Assigned jobs", "المهام المسندة") : role === "TENANT" ? t("My requests", "طلباتي") : t("Reports", "التقارير"), icon: ClipboardList }, { id: "calendar" as const, label: t("Calendar", "التقويم"), icon: CalendarDays }, { id: "messages" as const, label: t("Messages", "الرسائل"), icon: MessageSquare }, { id: "inquiries" as const, label: t("Inquiries", "الاستفسارات"), icon: CircleHelp }, { id: "profile" as const, label: t("Profile", "الملف الشخصي"), icon: UserRound }]; return <nav className="mt-3 space-y-1">{items.map(({ id, label, icon: Icon }) => <button key={id} onClick={() => onView(id)} aria-label={id === "profile" ? t("Profile and security", "الملف الشخصي والأمان") : undefined} className={`maintainr-demo-rail-nav flex w-full items-center gap-3 rounded-xl border px-3 py-3 text-start text-sm transition ${view === id ? "maintainr-demo-rail-nav-active border-teal-200 bg-teal-50 font-semibold text-teal-800 shadow-sm" : "border-transparent text-slate-400 hover:bg-white/[.05] hover:text-white"}`}><Icon size={17}/>{label}</button>)}</nav>; }

function Overview({ state, role, onView, onRun }: { state: DemoState; role: DemoRole; onView: (view: View) => void; onRun: (action: string, payload?: Record<string, unknown>) => Promise<DemoState | undefined> }) { const { t } = useLanguage(); const open = state.tickets.filter(ticket => ticket.status !== "RESOLVED").length; const active = state.tickets.filter(ticket => ticket.status === "ASSIGNED" || ticket.status === "IN_PROGRESS").length; const focus = state.tickets.find(ticket => ticket.status !== "RESOLVED"); return <div className="space-y-6"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label={t("Open tickets", "بلاغات مفتوحة")} value={String(open)} detail={t("Needs a next action", "تحتاج إلى إجراء تالٍ")}/><Metric label={t("In progress", "قيد التنفيذ")} value={String(active)} detail={t("Assigned and active", "مُسندة ونشطة")}/><Metric label={t("Resolved", "تم الحل")} value={String(state.tickets.filter(ticket => ticket.status === "RESOLVED").length)} detail={t("Retained completion", "إنجاز محفوظ")}/><Metric label={t("People", "الأشخاص")} value={String(state.people.filter(person => person.isActive).length)} detail={t("Active in workspace", "نشطون في مساحة العمل")}/></div><div className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><article className="maintainr-demo-card overflow-hidden rounded-2xl"><div className="flex items-center justify-between border-b border-[#e3eeeb] px-5 py-4 dark:border-white/[.07]"><div><p className="font-semibold">{t("Ticket operations", "عمليات البلاغات")}</p><p className="mt-1 text-xs text-[#56716d] dark:text-slate-400">{t("Track every maintenance request from report to resolution.", "تابع كل بلاغ صيانة من الإبلاغ حتى الحل.")}</p></div><button onClick={() => onView("requests")} className="text-xs font-semibold text-teal-700 dark:text-teal-200">{t("View tickets", "عرض البلاغات")}</button></div><div className="divide-y divide-[#eaf1ef] dark:divide-white/[.06]">{state.tickets.slice(0, 4).map(ticket => <TicketLine key={ticket.id} ticket={ticket}/>)}</div></article><article className="maintainr-demo-focus rounded-2xl bg-[linear-gradient(145deg,#0f766e,#087b92)] p-6 text-white shadow-[0_18px_42px_rgba(8,124,115,.18)]"><BellRing size={20} className="text-teal-100"/><p className="mt-8 text-xs font-semibold uppercase tracking-[.18em] text-teal-100">{t("Next focus", "التركيز التالي")}</p><h2 className="mt-4 text-2xl font-semibold leading-tight">{focus ? focus.title : t("Your active work is under control.", "أعمالك النشطة تحت السيطرة.")}</h2><p className="mt-3 text-sm leading-6 text-teal-50">{focus ? `${focus.unit} · ${focus.priority}` : t("Use reminders to keep planned work moving.", "استخدم التذكيرات لإبقاء العمل المخطط متقدماً.")}</p><button onClick={() => onView("reminders")} className="mt-7 text-sm font-semibold text-white underline decoration-teal-200/70 underline-offset-4">{t("View reminders", "عرض التذكيرات")}</button></article></div></div>; }
function Metric({ label, value, detail }: { label: string; value: string; detail: string }) { return <article className="maintainr-demo-card rounded-2xl p-5"><p className="text-xs font-bold uppercase tracking-[.13em] text-[#607a75] dark:text-slate-400">{label}</p><p className="mt-4 text-3xl font-semibold text-[#172a27] dark:text-white">{value}</p><p className="mt-2 text-xs text-[#56716d] dark:text-slate-400">{detail}</p></article>; }
function TicketLine({ ticket }: { ticket: DemoTicket }) { return <div className="flex items-center justify-between gap-3 px-5 py-4"><div className="min-w-0"><p className="truncate text-sm font-semibold text-[#1d3733] dark:text-white">{ticket.title}</p><p className="mt-1 text-xs text-[#56716d] dark:text-slate-400">{ticket.unit} · {ticket.priority}</p></div><Status ticket={ticket}/></div>; }
function Status({ ticket }: { ticket: DemoTicket }) { return <span className={`shrink-0 rounded-full border px-2.5 py-1 text-[10px] font-bold tracking-[.08em] ${statusTone[ticket.status]}`}>{ticket.status.replace("_", " ")}</span>; }

function ManagerSetup({ state, onRun, onView }: { state: DemoState; onRun: (action: string, payload?: Record<string, unknown>) => Promise<DemoState | undefined>; onView: (view: View) => void }) { const { t } = useLanguage(); const [unit, setUnit] = useState("B-101"); const [notice, setNotice] = useState(""); const [owner, setOwner] = useState({ name: "", email: "", unit: "A-204" }); const prepareUnit = () => setNotice(t(`Unit ${unit.toUpperCase()} is prepared for this safe demo session.`, `تم تجهيز الوحدة ${unit.toUpperCase()} لجلسة العرض الآمنة.`)); const createOwner = async () => { const next = await onRun("manager-create-account", { name: owner.name, email: owner.email, role: "FLAT_OWNER", unitCode: owner.unit }); if (next) setOwner({ name: "", email: "", unit: "A-204" }); }; return <div className="space-y-5"><article className="maintainr-demo-card overflow-hidden rounded-2xl"><div className="flex items-start justify-between gap-4 border-b border-[#e3eeeb] px-5 py-4 dark:border-white/[.07]"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-teal-700 dark:text-teal-200">{t("Workspace setup", "إعداد مساحة العمل")}</p><h2 className="mt-1 text-xl font-semibold">{t("Complete your Manager checklist", "أكمل قائمة مهام المدير")}</h2><p className="mt-2 text-sm text-[#56716d] dark:text-slate-400">{t("Start with the three actions that make a maintenance workspace ready to operate.", "ابدأ بالإجراءات الثلاثة التي تجعل مساحة عمل الصيانة جاهزة للتشغيل.")}</p></div><button onClick={() => setNotice(t("Checklist reviewed for this demo session.", "تمت مراجعة القائمة لجلسة العرض هذه."))} className="h-10 rounded-xl bg-teal-700 px-4 text-sm font-semibold text-white hover:bg-teal-800">{t("Mark complete", "وضع علامة مكتمل")}</button></div><div className="grid gap-3 p-5 md:grid-cols-3"><SetupStep icon={<Building2 size={18}/>} title={t("Set workspace identity", "حدد هوية مساحة العمل")} detail={t("Review naming, colors, and the shared portal presentation.", "راجع التسمية والألوان والعرض المشترك للبوابة.")} action={t("Open profile", "فتح الملف الشخصي")} onClick={() => onView("profile")}/><SetupStep icon={<Users size={18}/>} title={t("Prepare people access", "جهز وصول الأشخاص")} detail={t("Create demo roles, pause access, and assign team responsibility.", "أنشئ أدوار العرض وأوقف الوصول وعيّن مسؤوليات الفريق.")} action={t("Manage people", "إدارة الأشخاص")} onClick={() => onView("people")}/><SetupStep icon={<ClipboardList size={18}/>} title={t("Start the operating record", "ابدأ سجل التشغيل")} detail={t("Review tickets, planned visits, messages, and inquiries.", "راجع البلاغات والزيارات المخططة والرسائل والاستفسارات.")} action={t("View tickets", "عرض البلاغات")} onClick={() => onView("requests")}/></div></article><article className="maintainr-demo-card rounded-2xl p-5"><div className="flex items-center gap-2"><KeyRound size={18} className="text-teal-700 dark:text-teal-200"/><p className="font-semibold">{t("Account access", "وصول الحساب")}</p></div><p className="mt-2 text-sm text-[#56716d] dark:text-slate-400">{t("The public demo never emails real reset links. This control confirms the same manager workflow safely on isolated demo accounts.", "لا يرسل العرض العام روابط إعادة تعيين حقيقية عبر البريد. يؤكد هذا التحكم سير عمل المدير نفسه بأمان على حسابات العرض المعزولة.")}</p><div className="mt-4 flex flex-col gap-3 sm:flex-row"><input placeholder={t("User email address", "البريد الإلكتروني للمستخدم")} className="maintainr-demo-field h-11 flex-1 rounded-xl px-3 text-sm"/><button onClick={() => setNotice(t("Demo reset-link preparation confirmed. No email was sent.", "تم تأكيد تجهيز رابط إعادة التعيين للعرض. لم يتم إرسال بريد إلكتروني."))} className="h-11 rounded-xl bg-sky-600 px-4 text-sm font-semibold text-white hover:bg-sky-700">{t("Send reset link", "إرسال رابط إعادة التعيين")}</button></div></article><div className="grid gap-5 xl:grid-cols-2"><article className="maintainr-demo-card rounded-2xl p-5"><p className="font-semibold">{t("Prepare a unit", "تجهيز وحدة")}</p><p className="mt-2 text-sm text-[#56716d] dark:text-slate-400">{t("Use a unit code to keep every isolated demo account and work item scoped clearly.", "استخدم رمز الوحدة للحفاظ على نطاق واضح لكل حساب وعمل في العرض المعزول.")}</p><div className="mt-4 flex gap-3"><input value={unit} onChange={event => setUnit(event.target.value)} className="maintainr-demo-field h-11 flex-1 rounded-xl px-3 text-sm" placeholder="A-204"/><button onClick={prepareUnit} className="h-11 rounded-xl bg-teal-700 px-4 text-sm font-semibold text-white">{t("Prepare unit", "تجهيز الوحدة")}</button></div></article><article className="maintainr-demo-card rounded-2xl p-5"><p className="font-semibold">{t("Add a flat owner", "إضافة مالك شقة")}</p><p className="mt-2 text-sm text-[#56716d] dark:text-slate-400">{t("Create a separate isolated demo owner account and connect it to a unit.", "أنشئ حساب مالك عرض معزولاً منفصلاً واربطه بوحدة.")}</p><div className="mt-4 grid gap-3 sm:grid-cols-2"><input value={owner.name} onChange={event => setOwner({ ...owner, name: event.target.value })} placeholder={t("Owner name", "اسم المالك")} className="maintainr-demo-field h-11 rounded-xl px-3 text-sm"/><input value={owner.email} onChange={event => setOwner({ ...owner, email: event.target.value })} placeholder={t("Owner email", "بريد المالك")} className="maintainr-demo-field h-11 rounded-xl px-3 text-sm"/><input value={owner.unit} onChange={event => setOwner({ ...owner, unit: event.target.value })} placeholder={t("Unit code", "رمز الوحدة")} className="maintainr-demo-field h-11 rounded-xl px-3 text-sm"/><button disabled={!owner.name.trim() || !owner.email.trim()} onClick={createOwner} className="h-11 rounded-xl bg-teal-700 px-4 text-sm font-semibold text-white disabled:bg-slate-300">{t("Create owner account", "إنشاء حساب مالك")}</button></div></article></div>{notice && <p className="rounded-xl border border-teal-200 bg-teal-50 px-4 py-3 text-sm text-teal-800 dark:border-teal-400/20 dark:bg-teal-400/[.08] dark:text-teal-100">{notice}</p>}</div>; }
function SetupStep({ icon, title, detail, action, onClick }: { icon: React.ReactNode; title: string; detail: string; action: string; onClick: () => void }) { return <div className="rounded-2xl border border-[#e3eeeb] p-4 dark:border-white/[.07]"><span className="grid size-10 place-items-center rounded-xl bg-teal-50 text-teal-700 dark:bg-teal-400/10 dark:text-teal-200">{icon}</span><p className="mt-4 font-semibold">{title}</p><p className="mt-2 text-xs leading-5 text-[#56716d] dark:text-slate-400">{detail}</p><button onClick={onClick} className="mt-4 text-xs font-semibold text-teal-700 dark:text-teal-200">{action} →</button></div>; }
function Analytics({ state }: { state: DemoState }) { const { t } = useLanguage(); const total = Math.max(state.tickets.length, 1); const resolved = state.tickets.filter(ticket => ticket.status === "RESOLVED").length; const assigned = state.tickets.filter(ticket => ticket.status === "ASSIGNED" || ticket.status === "IN_PROGRESS").length; return <div className="grid gap-5 xl:grid-cols-[.9fr_1.1fr]"><article className="maintainr-demo-focus rounded-2xl p-6"><p className="text-xs font-bold uppercase tracking-[.18em]">{t("Operating health", "صحة التشغيل")}</p><p className="mt-5 text-5xl font-semibold">{Math.round((resolved / total) * 100)}%</p><p className="mt-2 text-sm text-teal-50">{t("Resolved maintenance requests in this isolated workspace.", "طلبات الصيانة المحلولة في مساحة العمل المعزولة هذه.")}</p><div className="mt-7 h-2 overflow-hidden rounded-full bg-white/20"><div className="h-full rounded-full bg-white" style={{ width: `${Math.max(8, (resolved / total) * 100)}%` }}/></div></article><article className="maintainr-demo-card rounded-2xl p-6"><p className="font-semibold">{t("Workload by status", "عبء العمل حسب الحالة")}</p><div className="mt-5 grid gap-4 sm:grid-cols-3"><Metric label={t("Open", "مفتوح")} value={String(total - resolved - assigned)} detail={t("Awaiting action", "بانتظار إجراء")}/><Metric label={t("Active", "نشط")} value={String(assigned)} detail={t("Assigned work", "عمل مسند")}/><Metric label={t("Resolved", "تم الحل")} value={String(resolved)} detail={t("Completion retained", "إنجاز محفوظ")}/></div></article></div>; }
function Calendar({ state, onRun }: { state: DemoState; onRun: (action: string, payload?: Record<string, unknown>) => Promise<DemoState | undefined> }) { const { t } = useLanguage(); const manager = state.account.role === "PROPERTY_MANAGER"; const [form, setForm] = useState({ title: "", scheduledStart: "", scheduledEnd: "", technicianId: String(state.technicians[0]?.id || "") }); const submit = () => onRun("manager-create-appointment", { ...form, technicianId: Number(form.technicianId) }).then(next => { if (next) setForm({ ...form, title: "", scheduledStart: "", scheduledEnd: "" }); }); return <div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]">{manager && <article className="maintainr-demo-card rounded-2xl p-6"><p className="font-semibold">{t("Schedule a visit", "جدولة زيارة")}</p><div className="mt-5 grid gap-3"><input value={form.title} onChange={event => setForm({ ...form, title: event.target.value })} placeholder={t("Visit title", "عنوان الزيارة")} className="maintainr-demo-field h-11 rounded-xl px-3 text-sm"/><input type="datetime-local" value={form.scheduledStart} onChange={event => setForm({ ...form, scheduledStart: event.target.value })} className="maintainr-demo-field h-11 rounded-xl px-3 text-sm"/><input type="datetime-local" value={form.scheduledEnd} onChange={event => setForm({ ...form, scheduledEnd: event.target.value })} className="maintainr-demo-field h-11 rounded-xl px-3 text-sm"/><select value={form.technicianId} onChange={event => setForm({ ...form, technicianId: event.target.value })} className="maintainr-demo-field h-11 rounded-xl px-3 text-sm">{state.technicians.map(tech => <option key={tech.id} value={tech.id}>{tech.name}</option>)}</select><button disabled={!form.title || !form.scheduledStart || !form.scheduledEnd || !form.technicianId} onClick={submit} className="h-11 rounded-xl bg-teal-700 text-sm font-semibold text-white disabled:bg-slate-300">{t("Schedule visit", "جدولة زيارة")}</button></div></article>}<article className="maintainr-demo-card rounded-2xl p-6"><p className="font-semibold">{t("Planned visits", "الزيارات المخططة")}</p><div className="mt-5 space-y-3">{state.appointments.length ? state.appointments.map(appointment => <AppointmentRow key={appointment.id} appointment={appointment}/>) : <p className="text-sm text-[#56716d] dark:text-slate-400">{t("No visits are scheduled for this role.", "لا توجد زيارات مجدولة لهذا الدور.")}</p>}</div></article></div>; }
function AppointmentRow({ appointment }: { appointment: DemoAppointment }) { return <div className="rounded-xl border border-[#e3eeeb] p-4 dark:border-white/[.07]"><p className="font-semibold">{appointment.title}</p><p className="mt-1 text-xs text-[#56716d] dark:text-slate-400">{new Date(appointment.scheduledStart).toLocaleString()} · {appointment.unit || "—"}</p><span className="mt-3 inline-flex rounded-full bg-sky-50 px-2.5 py-1 text-[10px] font-bold tracking-wide text-sky-700 dark:bg-sky-400/10 dark:text-sky-300">{appointment.status}</span></div>; }
function Messages({ conversations, onRun }: { conversations: DemoConversation[]; onRun: (action: string, payload?: Record<string, unknown>) => Promise<DemoState | undefined> }) { const { t } = useLanguage(); const [selected, setSelected] = useState<number | null>(conversations[0]?.id ?? null); const [body, setBody] = useState(""); const send = () => { if (!selected || !body.trim()) return; onRun("send-message", { conversationId: selected, body }).then(next => { if (next) setBody(""); }); }; return <div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><article className="maintainr-demo-card overflow-hidden rounded-2xl"><p className="border-b border-[#e3eeeb] px-5 py-4 font-semibold dark:border-white/[.07]">{t("Conversations", "المحادثات")}</p>{conversations.map(conversation => <button key={conversation.id} onClick={() => setSelected(conversation.id)} className={`w-full border-b border-[#eaf1ef] p-5 text-start dark:border-white/[.06] ${selected === conversation.id ? "bg-teal-50/70 dark:bg-teal-400/[.06]" : ""}`}><p className="font-semibold">{conversation.subject}</p><p className="mt-1 text-xs text-[#56716d] dark:text-slate-400">{conversation.kind} · {new Date(conversation.updatedAt).toLocaleString()}</p></button>)}</article><article className="maintainr-demo-card rounded-2xl p-6"><p className="font-semibold">{t("Message workspace", "مساحة الرسائل")}</p><p className="mt-2 text-sm text-[#56716d] dark:text-slate-400">{t("Send a safe isolated-demo message to verify the same workspace communication pattern.", "أرسل رسالة عرض معزولة آمنة للتحقق من نمط التواصل نفسه في مساحة العمل.")}</p><textarea value={body} onChange={event => setBody(event.target.value)} placeholder={t("Write a message", "اكتب رسالة")} className="maintainr-demo-field mt-5 min-h-32 w-full rounded-xl p-3 text-sm"/><button disabled={!selected || !body.trim()} onClick={send} className="mt-4 flex h-11 items-center gap-2 rounded-xl bg-teal-700 px-4 text-sm font-semibold text-white disabled:bg-slate-300"><Send size={16}/>{t("Send message", "إرسال رسالة")}</button></article></div>; }
function Inquiries({ inquiries }: { inquiries: DemoInquiry[] }) { const { t } = useLanguage(); return <div className="maintainr-demo-card overflow-hidden rounded-2xl"><div className="border-b border-[#e3eeeb] px-5 py-4 dark:border-white/[.07]"><p className="font-semibold">{t("Inquiries and complaints", "الاستفسارات والشكاوى")}</p></div>{inquiries.length ? <div className="divide-y divide-[#eaf1ef] dark:divide-white/[.06]">{inquiries.map(inquiry => <article key={inquiry.id} className="p-5"><div className="flex flex-wrap items-center gap-2"><p className="font-semibold">{inquiry.subject}</p><span className="rounded-full bg-amber-50 px-2.5 py-1 text-[10px] font-bold text-amber-700 dark:bg-amber-400/10 dark:text-amber-300">{inquiry.kind} · {inquiry.status}</span></div><p className="mt-3 text-sm text-[#56716d] dark:text-slate-400">{inquiry.body}</p><p className="mt-3 text-xs text-teal-700 dark:text-teal-200">{inquiry.unit || "—"} · {new Date(inquiry.createdAt).toLocaleDateString()}</p></article>)}</div> : <p className="p-8 text-center text-sm text-[#56716d] dark:text-slate-400">{t("No inquiries are waiting for review.", "لا توجد استفسارات بانتظار المراجعة.")}</p>}</div>; }
function Requests({ state, onRun }: { state: DemoState; onRun: (action: string, payload?: Record<string, unknown>) => Promise<DemoState | undefined> }) { const { t } = useLanguage(); const role = state.account.role; const [title, setTitle] = useState(""); const [description, setDescription] = useState(""); const [assignments, setAssignments] = useState<Record<number, string>>({}); return <div className="space-y-5">{role === "TENANT" && <form onSubmit={event => { event.preventDefault(); onRun("create-ticket", { title, description }).then(next => { if (next) { setTitle(""); setDescription(""); } }); }} className="maintainr-demo-card rounded-2xl border-teal-200 bg-teal-50/60 p-5 dark:border-teal-400/15 dark:bg-teal-400/[.05]"><p className="font-semibold">{t("Report a maintenance issue", "أبلغ عن مشكلة صيانة")}</p><div className="mt-4 grid gap-3"><input value={title} onChange={event => setTitle(event.target.value)} required placeholder={t("Issue title", "عنوان المشكلة")} className="maintainr-demo-field h-11 rounded-xl px-3 text-sm"/><textarea value={description} onChange={event => setDescription(event.target.value)} required minLength={10} placeholder={t("What should the team know?", "ما الذي يجب أن يعرفه الفريق؟")} className="maintainr-demo-field min-h-24 rounded-xl p-3 text-sm"/><button className="h-11 w-fit rounded-xl bg-teal-700 px-4 text-sm font-semibold text-white">{t("Submit request", "إرسال الطلب")}</button></div></form>}<article className="maintainr-demo-card overflow-hidden rounded-2xl"><div className="border-b border-[#e3eeeb] px-5 py-4 dark:border-white/[.07]"><p className="font-semibold">{role === "FLAT_OWNER" ? t("Unit maintenance history", "سجل صيانة الوحدة") : t("Maintenance requests", "طلبات الصيانة")}</p></div><div className="divide-y divide-[#eaf1ef] dark:divide-white/[.06]">{state.tickets.map(ticket => <article key={ticket.id} className="flex flex-col gap-4 p-5 lg:flex-row lg:items-center lg:justify-between"><div><div className="flex flex-wrap items-center gap-2"><p className="font-semibold">{ticket.title}</p><Status ticket={ticket}/></div><p className="mt-2 max-w-2xl text-sm text-[#56716d] dark:text-slate-400">{ticket.description}</p><p className="mt-2 text-xs font-medium text-teal-700 dark:text-teal-200">{ticket.unit} · {ticket.priority}</p></div><div className="flex shrink-0 flex-wrap gap-2">{role === "PROPERTY_MANAGER" && ticket.status === "OPEN" && <><select value={assignments[ticket.id] || String(state.technicians[0]?.id || "")} onChange={event => setAssignments({ ...assignments, [ticket.id]: event.target.value })} className="maintainr-demo-field h-10 rounded-xl px-2 text-xs">{state.technicians.map(tech => <option key={tech.id} value={tech.id}>{tech.name}</option>)}</select><button onClick={() => onRun("assign-ticket", { ticketId: ticket.id, technicianId: Number(assignments[ticket.id] || state.technicians[0]?.id) })} className="h-10 rounded-xl bg-teal-700 px-3 text-xs font-semibold text-white">{t("Assign technician", "تعيين فني")}</button></>}{role === "TECHNICIAN" && ticket.status === "ASSIGNED" && <button onClick={() => onRun("update-ticket", { ticketId: ticket.id, status: "IN_PROGRESS" })} className="h-10 rounded-xl bg-teal-700 px-3 text-xs font-semibold text-white">{t("Start work", "ابدأ العمل")}</button>}{role === "TECHNICIAN" && ticket.status === "IN_PROGRESS" && <button onClick={() => onRun("update-ticket", { ticketId: ticket.id, status: "RESOLVED" })} className="h-10 rounded-xl bg-teal-700 px-3 text-xs font-semibold text-white">{t("Mark resolved", "وضع علامة تم الحل")}</button>}</div></article>)}</div></article></div>; }
function Reminders({ state, onRun }: { state: DemoState; onRun: (action: string, payload?: Record<string, unknown>) => Promise<DemoState | undefined> }) { const { t } = useLanguage(); return <div className="grid gap-4">{state.reminders.length ? state.reminders.map(reminder => <article key={reminder.id} className="maintainr-demo-card rounded-2xl p-6"><div className="flex flex-col gap-4 sm:flex-row sm:justify-between"><div><p className="text-xs font-bold tracking-[.15em] text-teal-700 dark:text-teal-200">{t("PLANNED FOLLOW-UP", "متابعة مخططة")}</p><h2 className="mt-2 text-xl font-semibold">{reminder.title}</h2><p className="mt-3 text-sm text-[#56716d] dark:text-slate-400">{reminder.description}</p><p className="mt-3 text-xs text-[#56716d] dark:text-slate-400">{new Date(reminder.dueAt).toLocaleDateString()} {reminder.unit ? `· ${reminder.unit}` : ""}</p></div><span className={`h-fit rounded-full px-3 py-2 text-xs font-semibold ${reminder.isAcknowledged ? "bg-emerald-50 text-emerald-700 dark:bg-emerald-400/10 dark:text-emerald-300" : "bg-amber-50 text-amber-700 dark:bg-amber-400/10 dark:text-amber-300"}`}>{reminder.isAcknowledged ? t("Acknowledged", "تم التأكيد") : t("Upcoming", "قادم")}</span></div><button disabled={reminder.isAcknowledged} onClick={() => onRun("acknowledge-reminder", { reminderId: reminder.id })} className="mt-6 h-11 rounded-xl bg-teal-700 px-4 text-sm font-semibold text-white disabled:bg-slate-300">{reminder.isAcknowledged ? t("Acknowledged", "تم التأكيد") : t("Acknowledge reminder", "تأكيد التذكير")}</button></article>) : <article className="maintainr-demo-card rounded-2xl p-6 text-sm text-[#56716d] dark:text-slate-400">{t("No reminders are visible for this demo role.", "لا توجد تذكيرات مرئية لدور العرض هذا.")}</article>}</div>; }
function Profile({ state, onRun }: { state: DemoState; onRun: (action: string, payload?: Record<string, unknown>) => Promise<DemoState | undefined> }) { const { t } = useLanguage(); const [name, setName] = useState(state.account.name); const [phone, setPhone] = useState(state.account.phone || ""); const [avatarUrl, setAvatarUrl] = useState(state.account.avatarUrl || ""); const [currentPassword, setCurrentPassword] = useState(""); const [nextPassword, setNextPassword] = useState(""); const [confirm, setConfirm] = useState(""); useEffect(() => { setName(state.account.name); setPhone(state.account.phone || ""); setAvatarUrl(state.account.avatarUrl || ""); }, [state.account]); return <div className="grid gap-5 xl:grid-cols-2"><article className="maintainr-demo-card rounded-2xl p-6"><div className="flex items-center gap-3"><span className="grid size-14 place-items-center overflow-hidden rounded-2xl bg-teal-50 text-teal-700 dark:bg-teal-400/10 dark:text-teal-200">{avatarUrl ? <img src={avatarUrl} alt="" className="size-full object-cover"/> : <UserRound size={23}/>}</span><div><p className="font-semibold">{state.account.name}</p><p className="mt-1 text-xs text-[#56716d] dark:text-slate-400">{state.account.email} · {state.account.unitCode}</p></div></div><div className="mt-6 grid gap-3"><input value={name} onChange={event => setName(event.target.value)} placeholder={t("Full name", "الاسم الكامل")} className="maintainr-demo-field h-11 rounded-xl px-3 text-sm"/><input value={phone} onChange={event => setPhone(event.target.value)} placeholder={t("Phone number", "رقم الهاتف")} className="maintainr-demo-field h-11 rounded-xl px-3 text-sm"/><input value={avatarUrl} onChange={event => setAvatarUrl(event.target.value)} placeholder={t("Secure image URL (optional)", "رابط صورة آمن (اختياري)")} className="maintainr-demo-field h-11 rounded-xl px-3 text-sm"/><button onClick={() => onRun("update-profile", { name, phone, avatarUrl })} className="h-11 rounded-xl bg-teal-700 text-sm font-semibold text-white">{t("Save profile", "حفظ الملف الشخصي")}</button></div></article><article className="maintainr-demo-card rounded-2xl p-6"><div className="flex items-center gap-2"><KeyRound size={18} className="text-teal-700 dark:text-teal-200"/><p className="font-semibold">{t("Change demo password", "تغيير كلمة مرور العرض")}</p></div><p className="mt-2 text-xs leading-5 text-[#56716d] dark:text-slate-400">{t("This changes only the password for your isolated demo account. It cannot affect the live SaaS portal.", "يغيّر هذا كلمة مرور حساب العرض المعزول فقط ولا يمكنه التأثير على بوابة SaaS الحية.")}</p><div className="mt-5 grid gap-3"><input type="password" value={currentPassword} onChange={event => setCurrentPassword(event.target.value)} placeholder={t("Current demo password", "كلمة مرور العرض الحالية")} className="maintainr-demo-field h-11 rounded-xl px-3 text-sm"/><input type="password" value={nextPassword} onChange={event => setNextPassword(event.target.value)} placeholder={t("New demo password (8+ characters)", "كلمة مرور عرض جديدة (8 أحرف فأكثر)")} className="maintainr-demo-field h-11 rounded-xl px-3 text-sm"/><input type="password" value={confirm} onChange={event => setConfirm(event.target.value)} placeholder={t("Confirm new password", "تأكيد كلمة المرور الجديدة")} className="maintainr-demo-field h-11 rounded-xl px-3 text-sm"/><button disabled={currentPassword.length < 8 || nextPassword.length < 8 || nextPassword !== confirm} onClick={() => onRun("change-password", { currentPassword, nextPassword }).then(next => { if (next) { setCurrentPassword(""); setNextPassword(""); setConfirm(""); } })} className="h-11 rounded-xl bg-[#172a27] text-sm font-semibold text-white disabled:bg-slate-300 dark:bg-white dark:text-[#101521]">{t("Update password", "تحديث كلمة المرور")}</button></div></article></div>; }
function People({ state, onRun }: { state: DemoState; onRun: (action: string, payload?: Record<string, unknown>) => Promise<DemoState | undefined> }) { const { t } = useLanguage(); const [name, setName] = useState(""); const [email, setEmail] = useState(""); const [role, setRole] = useState<"TENANT" | "TECHNICIAN" | "FLAT_OWNER">("TENANT"); const [unitCode, setUnitCode] = useState("A-204"); return <div className="space-y-5"><article className="maintainr-demo-card rounded-2xl border-teal-200 bg-teal-50/60 p-6 dark:border-teal-400/15 dark:bg-teal-400/[.05]"><div className="flex items-center gap-2"><UserPlus size={19} className="text-teal-700 dark:text-teal-200"/><p className="font-semibold">{t("Create demo account", "إنشاء حساب عرض")}</p></div><p className="mt-2 text-xs leading-5 text-[#56716d] dark:text-slate-400">{t("Create a resident, technician, or owner inside the commercial demo only. New accounts begin with the current public demo password.", "أنشئ مستأجراً أو فنياً أو مالكاً داخل العرض التجاري فقط. تبدأ الحسابات الجديدة بكلمة مرور العرض العامة الحالية.")}</p><div className="mt-5 grid gap-3 md:grid-cols-2"><input value={name} onChange={event => setName(event.target.value)} placeholder={t("Full name", "الاسم الكامل")} className="maintainr-demo-field h-11 rounded-xl px-3 text-sm"/><input value={email} onChange={event => setEmail(event.target.value)} placeholder={t("Email address", "البريد الإلكتروني")} className="maintainr-demo-field h-11 rounded-xl px-3 text-sm"/><select value={role} onChange={event => setRole(event.target.value as typeof role)} className="maintainr-demo-field h-11 rounded-xl px-3 text-sm"><option value="TENANT">{t("Resident", "مستأجر")}</option><option value="TECHNICIAN">{t("Technician", "فني")}</option><option value="FLAT_OWNER">{t("Owner", "مالك")}</option></select><input value={unitCode} onChange={event => setUnitCode(event.target.value)} placeholder={t("Unit code", "رمز الوحدة")} className="maintainr-demo-field h-11 rounded-xl px-3 text-sm"/></div><button disabled={!name.trim() || !email.trim()} onClick={() => onRun("manager-create-account", { name, email, role, unitCode }).then(next => { if (next) { setName(""); setEmail(""); } })} className="mt-4 h-11 rounded-xl bg-teal-700 px-4 text-sm font-semibold text-white disabled:bg-slate-300">{t("Create demo account", "إنشاء حساب العرض")}</button></article><article className="maintainr-demo-card overflow-hidden rounded-2xl"><div className="border-b border-[#e3eeeb] px-5 py-4 dark:border-white/[.07]"><p className="font-semibold">{t("Demo people and access", "أشخاص ووصول العرض")}</p></div><div className="divide-y divide-[#eaf1ef] dark:divide-white/[.06]">{state.people.map(person => <PersonRow key={person.id} person={person} currentId={state.account.id} onRun={onRun}/>)}</div></article></div>; }
function PersonRow({ person, currentId, onRun }: { person: DemoPerson; currentId: number; onRun: (action: string, payload?: Record<string, unknown>) => Promise<DemoState | undefined> }) { const { t } = useLanguage(); return <div className="flex flex-col gap-3 p-5 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-semibold">{person.name}</p><p className="mt-1 text-xs text-[#56716d] dark:text-slate-400">{person.email} · {roleNames[person.role]} · {person.unitCode}</p></div><div className="flex items-center gap-3"><span className={`rounded-full px-2.5 py-1 text-xs font-semibold ${person.isActive ? "bg-emerald-50 text-emerald-700 dark:bg-emerald-400/10 dark:text-emerald-300" : "bg-slate-100 text-slate-600 dark:bg-white/[.06] dark:text-slate-300"}`}>{person.isActive ? t("Active", "نشط") : t("Paused", "موقوف")}</span>{person.id !== currentId && <button onClick={() => onRun("manager-set-account-status", { accountId: person.id, isActive: !person.isActive })} className="h-9 rounded-lg border border-[#cfe0dc] px-3 text-xs font-semibold text-teal-700 dark:border-white/[.1] dark:text-teal-200">{person.isActive ? t("Pause access", "إيقاف الوصول") : t("Restore access", "استعادة الوصول")}</button>}</div></div>; }
